var ENT=[["Loader", "Signature Loader pillar of the Inference Engine framework."], ["Quantizer", "Signature Quantizer pillar of the Inference Engine framework."], ["Router", "Signature Router pillar of the Inference Engine framework."], ["Streamer", "Signature Streamer pillar of the Inference Engine framework."], ["Budgeter", "Signature Budgeter pillar of the Inference Engine framework."], ["Validator", "Signature Validator pillar of the Inference Engine framework."], ["Harness", "Signature Harness pillar of the Inference Engine framework."]];
